import{_ as a,o,c as e,ag as r,j as s}from"./chunks/framework.KxDd3USm.js";const A=JSON.parse('{"title":"08.2 信息摘要、数字签名与证书 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"08-信息安全/02-摘要签名与证书.md","filePath":"08-信息安全/02-摘要签名与证书.md"}'),n={name:"08-信息安全/02-摘要签名与证书.md"},g={class:"fig"},l={"data-figure-id":"figure-44",viewBox:"0 0 720 260",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"数字签名流程：甲对正文求 Hash 摘要，用甲的私钥签名后发送正文和签名；乙对正文重算摘要，并用甲的公钥验证签名，两个摘要一致即确认来源和完整性。"},d={class:"fig"},i={"data-figure-id":"figure-45",viewBox:"0 0 720 196",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"先签后封流水线：甲依次经 Hash 求摘要、甲私钥签名、拼成明文的指令加签名、乙公钥封成密文信封；密文穿过网络到达乙，乙用乙私钥拆封、甲公钥验签并重算摘要比对。前三步正文仍是明文，第四步起才保密"},x={class:"fig"},h={"data-figure-id":"figure-46",viewBox:"0 0 680 165",width:"100%",style:{"max-width":"680px"},role:"img","aria-label":"数字证书信任链。根 CA 用私钥签发下级 CA 证书，下级 CA 签发网站证书；浏览器内置根 CA 公钥，逐级验证签名、有效期和吊销状态，确认网站公钥归属。"};function u(c,t,q,_,p,y){return o(),e("div",null,[t[6]||(t[6]=r('<h1 id="_08-2-信息摘要、数字签名与证书-★★★" tabindex="-1">08.2 信息摘要、数字签名与证书 ★★★ <a class="header-anchor" href="#_08-2-信息摘要、数字签名与证书-★★★" aria-label="Permalink to &quot;08.2 信息摘要、数字签名与证书 ★★★&quot;">​</a></h1><p><strong>动机</strong>：验证一份大文件&quot;有没有被改过一个字节&quot;，把整个文件倒来倒去比对太笨。办法：用 Hash 函数给文件算出一个短短的&quot;指纹&quot;——<strong>信息摘要</strong>。指纹变了哪怕一点点，文件必然动过。</p><h3 id="_3-1-hash-函数的四大特性" tabindex="-1">3.1 Hash 函数的四大特性 <a class="header-anchor" href="#_3-1-hash-函数的四大特性" aria-label="Permalink to &quot;3.1 Hash 函数的四大特性&quot;">​</a></h3><ol><li><strong>定长输出</strong>：无论输入多长（1 字节还是 1GB），输出固定长度；</li><li><strong>单向性</strong>：从摘要反推出原文，计算上不可行——所以也叫<strong>单向散列函数</strong>；</li><li><strong>抗碰撞性</strong>：找两个不同输入对应同一摘要，计算上不可行；</li><li><strong>雪崩效应</strong>：原文改动 1 个比特，摘要面目全非。</li></ol><p><strong>代表算法</strong>：<strong>MD5</strong>（摘要 <strong>128</strong> 位）、<strong>SHA-1</strong>（摘要 <strong>160</strong> 位）、SHA-256、国密 SM3。</p><h3 id="_3-2-摘要-加密-第二易错点" tabindex="-1">3.2 摘要 ≠ 加密（第二易错点） <a class="header-anchor" href="#_3-2-摘要-加密-第二易错点" aria-label="Permalink to &quot;3.2 摘要 ≠ 加密（第二易错点）&quot;">​</a></h3><p><strong>反例演示</strong>：选项「MD5 是一种加密算法」——<strong>错</strong>。摘要有两个&quot;非加密&quot;特征：① <strong>无密钥</strong>（任何人算同一个文件得到的摘要都一样）；② <strong>不可逆</strong>（加密要求能解密还原，摘要不能）。摘要的用途是<strong>完整性验证</strong>，不是保密。</p><p><strong>应试动作</strong>：背&quot;MD5-128、SHA-1-160&quot;两个数字 + 一句&quot;Hash 无密钥、不可逆、管完整性&quot;。考场上问&quot;属于信息摘要算法特性的是&quot;，挑&quot;定长输出/单向/抗碰撞&quot;；问&quot;MD5 摘要长度&quot;，答 128 位。</p><hr><h2 id="第四节-数字签名-★★★-永恒考点-必须能默写流程" tabindex="-1">第四节 数字签名 ★★★（永恒考点，必须能默写流程） <a class="header-anchor" href="#第四节-数字签名-★★★-永恒考点-必须能默写流程" aria-label="Permalink to &quot;第四节 数字签名 ★★★（永恒考点，必须能默写流程）&quot;">​</a></h2><p><strong>动机</strong>：公钥体系解决了保密，但有个新漏洞——乙收到&quot;甲&quot;发来的消息，怎么确认真是甲发的、而不是别人冒名的？而且甲事后赖账说&quot;我没发过&quot;怎么办？答案：让甲用<strong>只有自己才有的私钥</strong>处理一段消息。全世界只有甲能这么干，这就是<strong>数字签名</strong>——它一举解决<strong>真实性</strong>（确是甲发）和<strong>不可否认性</strong>（甲不能赖账），顺带用摘要比对保证<strong>完整性</strong>。</p><h3 id="_4-1-标准签名与验证流程-四步-背到能默写" tabindex="-1">4.1 标准签名与验证流程（四步，背到能默写） <a class="header-anchor" href="#_4-1-标准签名与验证流程-四步-背到能默写" aria-label="Permalink to &quot;4.1 标准签名与验证流程（四步，背到能默写）&quot;">​</a></h3><p>以甲发消息给乙为例：</p><ol><li><strong>生成摘要</strong>：甲用<strong>单向 Hash 函数</strong>对正文算出信息摘要；</li><li><strong>签名</strong>：甲用<strong>自己的私钥</strong>对摘要加密——这一步就是&quot;签名&quot;；</li><li><strong>发送</strong>：甲把<strong>正文 + 已签名的摘要</strong>一起发给乙；</li><li><strong>验证</strong>：乙用<strong>同一个 Hash 函数</strong>对收到的正文重新算出新摘要；再用<strong>甲的公钥</strong>解开签名得到原摘要；两者一致 → 消息确实出自甲、且中途未被改。</li></ol><p><strong>为什么只签&quot;摘要&quot;、不签&quot;全文&quot;？<strong>两个原因，背下来回答&quot;为什么不能对全文签名&quot;的题：① <strong>慢</strong>——签名用的是非对称（公钥）运算，天生慢，大文件全文签一遍开销巨大；② <strong>摘要短、够等价</strong>——Hash 摘要定长（如 128 位）且有雪崩效应，正文动一个字节摘要就面目全非，比对这个短摘要</strong>完全等价于</strong>比对整篇全文。所以标准做法永远是&quot;<strong>先算摘要、再签摘要</strong>&quot;——这正是 Hash 在数字签名里不可替代的位置。</p>',15)),s("figure",g,[(o(),e("svg",l,[...t[0]||(t[0]=[r('<defs><marker id="s" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text x="70" y="28" class="t">甲（发送方）</text><text x="515" y="28" class="t">乙（接收方）</text><rect x="35" y="50" width="105" height="38" rx="8" class="b"></rect><text x="65" y="74" class="t">正文</text><rect x="170" y="50" width="105" height="38" rx="8" class="g"></rect><text x="198" y="74" class="t">Hash 摘要</text><path d="M140 69H169" class="e" marker-end="url(#s)"></path><rect x="170" y="112" width="105" height="38" rx="8" class="b"></rect><text x="181" y="136" class="t">甲私钥签名</text><path d="M222 88V111" class="e" marker-end="url(#s)"></path><path d="M275 131H440" class="e" marker-end="url(#s)"></path><text x="306" y="119" class="s">正文 + 已签名摘要</text><rect x="462" y="105" width="105" height="38" rx="8" class="b"></rect><text x="474" y="129" class="t">甲公钥验签</text><rect x="590" y="50" width="95" height="38" rx="8" class="g"></rect><text x="612" y="74" class="t">重算摘要</text><path d="M567 123L635 89" class="e" marker-end="url(#s)"></path><text x="360" y="190" class="t" text-anchor="middle">两份摘要一致 → 来源真实、内容完整、不可否认</text>',19)])])),t[1]||(t[1]=s("figcaption",null,"签名用发送方私钥，验证用发送方公钥；它不提供正文保密，保密还要额外用接收方公钥加密。",-1))]),t[7]||(t[7]=r('<h3 id="_4-2-方向速查表-考场填空就查这张" tabindex="-1">4.2 方向速查表（考场填空就查这张） <a class="header-anchor" href="#_4-2-方向速查表-考场填空就查这张" aria-label="Permalink to &quot;4.2 方向速查表（考场填空就查这张）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>谁的什么钥</th><th>为什么</th></tr></thead><tbody><tr><td>甲<strong>签名</strong></td><td><strong>甲的私钥</strong></td><td>私钥唯一，签了就赖不掉</td></tr><tr><td>乙<strong>验证签名</strong></td><td><strong>甲的公钥</strong></td><td>公钥配对私钥，能解开才证明是甲签的</td></tr><tr><td>乙<strong>验证数字证书</strong></td><td><strong>CA 的公钥</strong></td><td>证书是 CA 签的名（见第五节）</td></tr><tr><td>发密文给对方</td><td><strong>对方的公钥</strong></td><td>保密方向</td></tr></tbody></table><p><strong>反例演示</strong>：真题选项里的三大错误方向——「乙用<strong>乙的公钥</strong>验证」（错，验证必须用<strong>发方</strong>甲的公钥，乙自己的钥匙对是拆&quot;发给乙的密文&quot;用的）；「甲用<strong>甲的公钥</strong>签名」（错，公钥人人有，谁都能&quot;签&quot;，就证明不了身份）；「甲用<strong>乙的私钥</strong>签名」（错，乙的私钥甲根本拿不到）。</p><h3 id="_4-3-签名-保密-一步不乱-真题最爱组合" tabindex="-1">4.3 签名 + 保密，一步不乱（真题最爱组合） <a class="header-anchor" href="#_4-3-签名-保密-一步不乱-真题最爱组合" aria-label="Permalink to &quot;4.3 签名 + 保密，一步不乱（真题最爱组合）&quot;">​</a></h3><p><strong>动机</strong>：签名流程里&quot;正文 + 签名摘要&quot;是<strong>明文</strong>发的——只解决了身份和完整性，<strong>没解决机密性</strong>。若既要保密又要签名，就在第 3 步外面再套一层数字信封（2.3 节）。完整流程（背诵模板）：</p><blockquote><p>甲：Hash 求摘要 → <strong>甲私钥</strong>签名摘要 → （正文+签名）用 <strong>乙公钥</strong> 加密发出 乙：<strong>乙私钥</strong>解密 → <strong>甲公钥</strong>验签名 → 同一 Hash 重算摘要比对</p></blockquote><p>记忆口诀：&quot;<strong>先签后封，私签公验；封用收方公，拆用收方私</strong>&quot;。</p><p><strong>六步逐帧演示</strong>（就用课后第 16 题的场景：客户甲向银行乙提交转账指令，要求①只有乙能读、②乙能确认出自甲且未被篡改）。每步看清两件事——<strong>用的谁的什么钥</strong>、<strong>报文此刻长什么样</strong>：</p><table tabindex="0"><thead><tr><th>步</th><th>谁做什么</th><th>用谁的什么钥</th><th>报文此刻的样子</th><th>此刻谁能看懂正文</th></tr></thead><tbody><tr><td>1</td><td>甲对指令 M 求摘要</td><td>Hash 函数（无密钥）</td><td>M + H</td><td>所有人（还是明文！）</td></tr><tr><td>2</td><td>甲对 H 签名</td><td><strong>甲的私钥</strong></td><td>M + 甲私钥(H)</td><td>所有人能看 M；签名只有甲的公钥能解</td></tr><tr><td>3</td><td>甲拼好待发</td><td>——</td><td>M + 签名（<strong>正文仍是明文</strong>）</td><td>所有人——这正是&quot;只签不封&quot;的漏洞</td></tr><tr><td>4</td><td>甲把整包封进数字信封</td><td><strong>乙的公钥</strong></td><td>乙公钥(M + 签名) = 密文 E</td><td><strong>只有乙</strong></td></tr><tr><td>5</td><td>乙拆信封</td><td><strong>乙的私钥</strong></td><td>还原出 M + 签名</td><td>乙</td></tr><tr><td>6</td><td>乙验签+重算比对</td><td><strong>甲的公钥</strong> + 同一 Hash</td><td>解出 H₁；对 M 重算得 H₂；H₁=H₂ → 真实+完整</td><td>——</td></tr></tbody></table>',9)),s("figure",d,[(o(),e("svg",i,[...t[2]||(t[2]=[r('<defs><marker id="sg-a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text class="who" x="14" y="20">甲</text><text class="who" x="640" y="20">乙</text><rect class="bx" x="40" y="34" width="96" height="42" rx="8"></rect><text class="tt" x="88" y="52">① Hash</text><text class="st" x="88" y="68">指令 → 摘要 H</text><rect class="au" x="148" y="34" width="96" height="42" rx="8"></rect><text class="tt" x="196" y="52">② 签名</text><text class="st" x="196" y="68">H → 签名块</text><text class="ky kg" x="196" y="90">甲的私钥</text><rect class="bx" x="256" y="34" width="96" height="42" rx="8"></rect><text class="tt" x="304" y="52">③ 拼接</text><text class="st" x="304" y="68">指令 + 签名</text><rect class="se" x="364" y="34" width="96" height="42" rx="8"></rect><text class="tt" x="412" y="52">④ 封信封</text><text class="st" x="412" y="68">整包 → 密文 E</text><text class="ky ko" x="412" y="90">乙的公钥</text><path class="e" d="M136 55 H146" marker-end="url(#sg-a)"></path><path class="e" d="M244 55 H254" marker-end="url(#sg-a)"></path><path class="e" d="M352 55 H362" marker-end="url(#sg-a)"></path><rect x="470" y="40" width="52" height="30" rx="14" fill="var(--surface-2)" stroke="var(--line-strong)"></rect><text class="st" x="496" y="53">网络</text><text class="st" x="496" y="64">窃听者</text><path class="e" d="M460 55 H468 M522 55 H546" marker-end="url(#sg-a)"></path><rect class="se" x="550" y="34" width="80" height="42" rx="8"></rect><text class="tt" x="590" y="52">⑤ 拆封</text><text class="st" x="590" y="68">E → 指令+签名</text><text class="ky ko" x="590" y="90">乙的私钥</text><rect class="au" x="642" y="34" width="72" height="42" rx="8"></rect><text class="tt" x="678" y="52">⑥ 验签</text><text class="st" x="678" y="68">比对 H₁ H₂</text><text class="ky kg" x="678" y="90">甲的公钥</text><path class="e" d="M536 55 V55"></path><path class="e" d="M630 55 H640" marker-end="url(#sg-a)"></path><rect x="40" y="106" width="312" height="20" rx="10" fill="var(--surface-2)"></rect><text class="st" x="196" y="120" fill="var(--ink)">①～③ 段：正文始终明文——能防伪造冒名，还不保密</text><rect x="364" y="106" width="158" height="20" rx="10" fill="var(--gold-soft)"></rect><text class="st" x="443" y="120" fill="var(--ink)">④ 起：密文段，只有乙能拆</text><text class="st" x="360" y="152" fill="var(--muted)">红色 = 认证方向（甲私钥签、甲公钥验）；金色 = 保密方向（乙公钥封、乙私钥拆）</text><text class="st" x="360" y="176" fill="var(--muted)">顺序锚点：先认证后保密——签名管&quot;是不是真的&quot;，信封管&quot;看不看得到&quot;</text>',40)])])),t[3]||(t[3]=s("figcaption",null,"对照课后第 16 题五问，每一问都落在这张图的某一步上；第（5）问的重放攻击见下。",-1))]),t[8]||(t[8]=r('<p><strong>反例演示（易错）</strong>：① 拆信封用<strong>乙的私钥</strong>、验签名用<strong>甲的公钥</strong>——两把钥匙来自两对不同的密钥对，考场最常把&quot;验签&quot;错写成&quot;用乙的公钥&quot;；② 流程全对也可能栽在第 16 题第（5）问：攻击者把<strong>昨天合法的整段密文原样重发</strong>，验签照样通过（确实是甲签的）——签名和加密都防不了&quot;重放&quot;，防它要靠<strong>时间戳/一次性随机数/序号</strong>让旧报文作废。</p><p><strong>应试动作</strong>：这是本课最高频考法。把 4.2 的速查表背熟，无论题干怎么换人名（甲乙/AB/发送接收方），第一步先问自己&quot;这个动作是<strong>保密</strong>还是<strong>认证</strong>&quot;——保密走对方公钥，认证走自己私钥。案例题风格题见本课末尾第 16 题。</p><hr><h2 id="第五节-数字证书与-ca-★★" tabindex="-1">第五节 数字证书与 CA ★★ <a class="header-anchor" href="#第五节-数字证书与-ca-★★" aria-label="Permalink to &quot;第五节 数字证书与 CA ★★&quot;">​</a></h2><p><strong>动机</strong>：非对称体系还剩最后一个窟窿——<strong>公钥怎么证明是本人的</strong>？乙手里那把&quot;甲的公钥&quot;，万一是攻击者伪造的（攻击者把自己的公钥冒充成甲的发给你），后面整个签名验证都白搭。<strong>数字证书</strong>就是给公钥办的&quot;身份证&quot;：由一个大家信任的权威机构 <strong>CA（证书授权中心）</strong>，把&quot;用户身份 + 用户公钥&quot;捆在一起并盖章。</p><h3 id="_5-1-证书里有什么、怎么验证" tabindex="-1">5.1 证书里有什么、怎么验证 <a class="header-anchor" href="#_5-1-证书里有什么、怎么验证" aria-label="Permalink to &quot;5.1 证书里有什么、怎么验证&quot;">​</a></h3><ul><li><p><strong>证书内容</strong>：用户身份信息、<strong>用户的公钥</strong>、证书有效期、序列号，以及最关键的——<strong>CA 用自己的私钥对证书摘要做的数字签名</strong>。</p></li><li><p><strong>验证证书（三步，别只停在&quot;验签名&quot;）</strong>：拿到一张证书，除了用 <strong>CA 的公钥</strong>验 CA 的签名，还要再查两件事才算有效：</p><ol><li><strong>验签名</strong>：用 <strong>CA 的公钥</strong>解开证书上的 CA 签名，比对摘要 → 确认这张证书确实是 CA 签发的、不是伪造的；</li><li><strong>查有效期</strong>：确认证书<strong>当前在有效期内</strong>（未过期、也未被提前撤销）；</li><li><strong>查吊销</strong>：到 CA 或证书库查这张证书<strong>是否已被列入吊销列表（CRL）</strong>——私钥泄露、用户离职都可能让 CA 提前作废证书，正文却仍&quot;未过期&quot;。</li></ol><p>三步全过，才证明&quot;<strong>这把公钥确实属于这个人、且当前有效</strong>&quot;。</p></li><li><p><strong>信任链与根证书</strong>：未必每个 CA 都天生被信任。现实里是一串&quot;<strong>信任链</strong>&quot;——顶层有一个大家都信任的<strong>根证书</strong>（内置在操作系统/浏览器里），它给下层 CA 签发证书，下层 CA 再给普通用户签发；验证时逐级向上，直到找到一个你本来就信任的根证书为止。选择题若问&quot;浏览器为什么凭内置根证书就能信某个 CA 签的证书&quot;，本质就是靠这条自下而上的信任链。</p></li><li><p>CA 的职责：证书的签发、更新、<strong>撤销（吊销列表 CRL）</strong>、管理。</p></li></ul><h3 id="_5-2-与第-6-课联动" tabindex="-1">5.2 与第 6 课联动 <a class="header-anchor" href="#_5-2-与第-6-课联动" aria-label="Permalink to &quot;5.2 与第 6 课联动&quot;">​</a></h3><p>浏览器地址栏的 <strong>HTTPS</strong>（端口 443，见 <a href="/ruankao/06-计算机网络/06-应用层协议.html">06-计算机网络.md</a>）握手时就用到这一套：服务器出示<strong>数字证书</strong>，浏览器用 <strong>CA 的公钥</strong>验证书，确认服务器身份后再协商对称会话密钥加密通信——&quot;证书验身份 + 对称管数据&quot;的组合再现。</p><p><strong>反例演示</strong>：选项「验证数字证书要用证书持有者的公钥」——<strong>错</strong>。证书上的签名是 <strong>CA</strong> 签的，所以要用 <strong>CA 的公钥</strong>验。持有者的公钥是证书<strong>里装的东西</strong>，不是验证工具。</p><p><strong>应试动作</strong>：背两句——&quot;证书 = 身份 + 公钥 + CA 签名&quot;；&quot;验证书用 CA 的公钥，验证普通签名用发送者的公钥&quot;。考场给场景问&quot;浏览器如何确认某网站公钥的真实性&quot;，答&quot;用 CA 公钥验证网站的数字证书&quot;。</p>',11)),s("figure",x,[(o(),e("svg",h,[...t[4]||(t[4]=[r('<defs><marker id="cert" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><rect x="35" y="55" width="120" height="46" rx="8" class="b"></rect><text x="64" y="78" class="t">根 CA</text><text x="51" y="94" class="t">内置公钥</text><rect x="280" y="55" width="120" height="46" rx="8" class="b"></rect><text x="302" y="78" class="t">下级 CA</text><text x="300" y="94" class="t">签发证书</text><rect x="525" y="55" width="120" height="46" rx="8" class="b"></rect><text x="555" y="78" class="t">网站证书</text><text x="536" y="94" class="t">身份 + 公钥</text><path d="M155 78H279M400 78H524" class="e" marker-end="url(#cert)"></path><text x="178" y="49" class="t">根私钥签下级</text><text x="422" y="49" class="t">CA 私钥签网站</text><text x="120" y="142" class="t">浏览器：逐级验签 + 查有效期 + 查 CRL 吊销状态</text>',14)])])),t[5]||(t[5]=s("figcaption",null,"证书验证使用签发者 CA 的公钥；证书持有者公钥是被验证的内容，不是验签工具。",-1))]),t[9]||(t[9]=s("hr",null,null,-1))])}const m=a(n,[["render",u]]);export{A as __pageData,m as default};
